steps.command:
ServiceManager.sessionId = null;

var ReportReceipts = ReceiptBatch_get_report_rpa_dataResponse.Response
    .ReceiptBatch_get_report_rpa_dataTableArray
    .ReceiptBatch_get_report_rpa_dataArrayItem;
var receiptIdsCount = ReportReceipts.length;
var ReportPurpose = receiptIdsCount > 0 ? ReportReceipts[0].REPORT_PURPOSE : "";

function formatEbsDate(value) {
    if (!value) {
        return "";
    }

    var parts = value.split("-");
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
                  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    return parts[2] + "-" + months[Number(parts[1]) - 1] + "-" + parts[0];
}

function valueOrEmpty(value) {
    return value === null || value === undefined ? "" : value;
}

var receipt = typeof ReportReceipts === "undefined" || ReportReceipts === null
    ? undefined
    : ReportReceipts[index_0];

if (!receipt || typeof receipt !== "object" || Array.isArray(receipt)) {
    throw new Error("cashLine Parameters: no report receipt at the current loop index.");
}

var currentReceiptId = receipt.RECEIPT_ID;
if (currentReceiptId === null || currentReceiptId === undefined ||
        String(currentReceiptId).trim() === "") {
    throw new Error("cashLine Parameters: the current report receipt has no receipt ID.");
}

var expenseData = receipt.EXPENSE_DATA_JSON;

if (typeof expenseData === "string") {
    var expenseDataText = expenseData.trim();
    if (expenseDataText === "") {
        expenseData = null;
    } else {
        try {
            expenseData = JSON.parse(expenseDataText);
        } catch (parseFailure) {
            throw new Error("cashLine Parameters: the receipt expense data JSON is invalid.");
        }
    }
}

if (expenseData !== null && expenseData !== undefined &&
        typeof expenseData !== "object") {
    throw new Error("cashLine Parameters: the receipt expense data JSON is invalid.");
}

var line =
    expenseData &&
    Array.isArray(expenseData.lines) &&
    expenseData.lines.length > 0
        ? expenseData.lines[0]
        : {};

var expenseType = valueOrEmpty(receipt.EXPENSE_TYPE);
var totalAmount = valueOrEmpty(receipt.TOTAL_AMOUNT);
var receiptDate = valueOrEmpty(receipt.RECEIPT_DATE);
var merchant = valueOrEmpty(receipt.MERCHANT);
var location = valueOrEmpty(receipt.LOCATION);
var department = valueOrEmpty(receipt.DEPARTMENT);

var attachmentPath = "";
var LocationName = location;
var DetailReceiptMissing = valueOrEmpty(line.originalReceiptMissing);
var CompanyAttendees = valueOrEmpty(line.companyAttendees);
var ReceiptCurrencyChoice = valueOrEmpty(line.receiptCurrency);
if (String(ReceiptCurrencyChoice).trim() === "") {
    ReceiptCurrencyChoice = "USD - US dollar";
}
var DetailReceiptAmount = totalAmount;
var StartDate = receiptDate;
var StartDateFormatted = formatEbsDate(receiptDate);
// var Justification = valueOrEmpty(line.justification);
var reportPurpose = typeof ReportPurpose === "undefined" || ReportPurpose === null
    ? ""
    : ReportPurpose;
var Justification = String(valueOrEmpty(line.justification)).trim() === ""
                     ? reportPurpose
                     : line.justification;
var ExchRate = valueOrEmpty(line.exchangeRate);
var DetailMerchantName = merchant;
var AirTravelType = valueOrEmpty(line.travelType);
var AirTicketClass = valueOrEmpty(line.ticketClass);
var AirFromLocation = valueOrEmpty(line.locationFrom);
var AirToLocation = valueOrEmpty(line.locationTo);
var NumberOfDays = valueOrEmpty(line.numberOfDays);
var AccEndDate = valueOrEmpty(line.endDate);
var AccEndDateFormatted = AccEndDate;
var MealAttendees = line.employees || [];
var MealGuests = line.guest || [];
var GuestEmployers = MealGuests.map(function (guest) {
    return guest.employer == null ? "" : guest.employer;
});
var MealNumberAttendees = MealAttendees.length + MealGuests.length;
